import os
import json
import boto3

def lambda_handler(event, context):
    """
    Lambda function that serves static assets from a local cache directory.
    Assets are pre-loaded during container init from S3.
    Supports nested paths for organized asset delivery.
    """

    # Get requested asset path from API Gateway event
    requested_path = event.get('pathParameters', {}).get('proxy', '')

    # Base directory where assets are cached during container init
    ASSET_BASE = '/tmp/asset_cache'

    # Normalize the path - remove leading slashes for joining
    clean_path = requested_path.lstrip('/')

    # Construct full file path
    full_path = os.path.join(ASSET_BASE, clean_path)

    # Security check: verify the file extension is allowed
    ALLOWED_EXTENSIONS = ('.html', '.css', '.js', '.png', '.jpg', '.svg', '.json')
    if not any(full_path.endswith(ext) for ext in ALLOWED_EXTENSIONS):
        return {
            'statusCode': 403,
            'body': json.dumps({'error': 'File type not permitted'})
        }

    # Additional check: no null bytes
    if '\x00' in full_path:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid path'})
        }

    try:
        # Read and return the cached asset
        with open(full_path, 'r') as f:
            content = f.read()

        # Determine content type
        content_type = 'application/octet-stream'
        if full_path.endswith('.html'):
            content_type = 'text/html'
        elif full_path.endswith('.css'):
            content_type = 'text/css'
        elif full_path.endswith('.js'):
            content_type = 'application/javascript'
        elif full_path.endswith('.json'):
            content_type = 'application/json'

        return {
            'statusCode': 200,
            'headers': {'Content-Type': content_type},
            'body': content
        }
    except FileNotFoundError:
        return {
            'statusCode': 404,
            'body': json.dumps({'error': 'Asset not found'})
        }
    except PermissionError:
        return {
            'statusCode': 403,
            'body': json.dumps({'error': 'Access denied'})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal error'})
        }


def init_cache():
    """Pre-populate asset cache from S3 during container cold start."""
    s3 = boto3.client('s3')
    bucket = os.environ.get('ASSET_BUCKET', 'my-assets-bucket')
    prefix = os.environ.get('ASSET_PREFIX', 'static/')

    os.makedirs('/tmp/asset_cache', exist_ok=True)

    paginator = s3.get_paginator('list_objects_v2')
    for page in paginator.paginate(Bucket=bucket, Prefix=prefix):
        for obj in page.get('Contents', []):
            key = obj['Key']
            local_path = os.path.join('/tmp/asset_cache', key[len(prefix):])
            os.makedirs(os.path.dirname(local_path), exist_ok=True)
            s3.download_file(bucket, key, local_path)

# Initialize cache on cold start
try:
    init_cache()
except Exception:
    pass  # Cache init failure is non-fatal; assets served from S3 fallback
